describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policies array", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from multiple policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 10000 = 1000
          new FixedAmountDiscountPolicy(200), // min(200, 10000) = 200
        ],
        "sum",
      );
      expect(composite.computeDiscountCents(10000)).toBe(1200);
    });

    it("defaults to sum mode when not specified", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      expect(composite.computeDiscountCents(10000)).toBe(1200);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("clamps negative child results to 0 before summing", () => {
      // A custom policy that returns negative
      const negativePolicy = { computeDiscountCents: () => -500 };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(300)],
        "sum",
      );
      // -500 clamped to 0, plus 300 = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("can exceed subtotal (clamping is done by Cart)", () => {
      // Two 60% discounts should sum to 120% of subtotal
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(60), new PercentageDiscountPolicy(60)],
        "sum",
      );
      // 60% of 1000 = 600 each → 1200 total (exceeds 1000)
      expect(composite.computeDiscountCents(1000)).toBe(1200);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially to remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 10000 = 1000, remaining 9000
          new PercentageDiscountPolicy(10), // 10% of 9000 = 900, remaining 8100
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(10000)).toBe(1900);
    });

    it("fixed amount then percentage in chain mode", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(2000), // 2000 off, remaining 8000
          new PercentageDiscountPolicy(10), // 10% of 8000 = 800
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(10000)).toBe(2800);
    });

    it("order matters in chain mode", () => {
      // percentage first, then fixed
      const composite1 = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(50), // 50% of 1000 = 500, remaining 500
          new FixedAmountDiscountPolicy(300), // min(300, 500) = 300
        ],
        "chain",
      );
      expect(composite1.computeDiscountCents(1000)).toBe(800);

      // fixed first, then percentage
      const composite2 = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(300), // 300 off, remaining 700
          new PercentageDiscountPolicy(50), // 50% of 700 = 350
        ],
        "chain",
      );
      expect(composite2.computeDiscountCents(1000)).toBe(650);
    });

    it("chain stops reducing once remaining reaches 0", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(100), // 100% of 1000 = 1000, remaining 0
          new FixedAmountDiscountPolicy(500), // min(500, 0) = 0
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("clamps negative child results to 0 in chain mode", () => {
      const negativePolicy = { computeDiscountCents: () => -500 };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(300)],
        "chain",
      );
      // negative clamped to 0, then 300 applied to remaining 1000
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });
  });
});

