        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 5000, costCents: 1200 },
      ],
      2000,
    );

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns 0 when total weight is 0 (no weightGrams)", () => {
      const lines = [makeLine("a", 1000, 1)]; // no weight
      expect(calc.computeShippingCents(lines, 1000)).toBe(0);
    });

    it("selects first bracket for weight within it", () => {
      const lines = [makeLine("a", 1000, 1, 300)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("selects first bracket at exact boundary", () => {
      const lines = [makeLine("a", 1000, 1, 500)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("selects second bracket just above first boundary", () => {
      const lines = [makeLine("a", 1000, 1, 501)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(700);
    });

    it("selects last bracket at its boundary", () => {
      const lines = [makeLine("a", 1000, 1, 5000)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(1200);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const lines = [makeLine("a", 1000, 1, 5001)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(2000);
    });

    it("falls back to heaviest bracket cost when no overflow specified", () => {
      const calcNoOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
      ]);
      const lines = [makeLine("a", 1000, 1, 3000)];
      expect(calcNoOverflow.computeShippingCents(lines, 1000)).toBe(700);
    });

    it("sorts brackets internally regardless of input order", () => {
      const calcUnsorted = new WeightBasedShippingCalculator([
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 500, costCents: 300 },
      ]);
      const lines = [makeLine("a", 1000, 1, 400)];
      expect(calcUnsorted.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("sums weight across multiple lines with quantity", () => {
      // 200g * 2 = 400g + 600g * 1 = 600g → total 1000g → second bracket (700)
      const lines = [
        makeLine("a", 1000, 2, 200),
        makeLine("b", 500, 1, 600),
      ];
      expect(calc.computeShippingCents(lines, 2500)).toBe(700);
    });
  });
});

