    ];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("fetch failed")),
    };
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow("fetch failed");
  });

  it("does not mutate original lines", async () => {
    const original: CartLine[] = [
      { product: { id: "a", name: "Widget", unitPriceCents: 100 }, quantity: 2 },
    ];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(999),
    };
    await refreshPrices(original, fetcher);
    expect(original[0]!.product.unitPriceCents).toBe(100);
  });
});

import { describe, it, expect, vi, beforeEach } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product, CartLine } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import { InventoryError } from "../src/inventory.ts";

function makeProduct(
  id: string,
  unitPriceCents: number,
  weightGrams?: number,
): Product {
  return { id, name: `Product ${id}`, unitPriceCents, weightGrams };
}

describe("Cart", () => {
  describe("add", () => {
    it("adds a product to the cart", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 1000), 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantity when adding same product twice", () => {
      const cart = new Cart();
      const product = makeProduct("a", 1000);
      cart.add(product, 2);
      cart.add(product, 3);
      expect(cart.itemCount).toBe(5);
    });

    it("rejects zero quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(makeProduct("a", 100), 0)).toThrow(RangeError);
    });

    it("rejects negative quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(makeProduct("a", 100), -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(makeProduct("a", 100), 1.5)).toThrow(RangeError);
    });

    it("rejects negative unitPriceCents", () => {
      const cart = new Cart();
      expect(() => cart.add(makeProduct("a", -1), 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes an existing product and returns true", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 1000), 1);
      expect(cart.remove("a")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product", () => {
      const cart = new Cart();
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity of existing product", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 1000), 2);
      cart.updateQuantity("a", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity is set to 0", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 1000), 2);
      cart.updateQuantity("a", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for unknown product", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("unknown", 5)).toThrow(
        "Product unknown is not in the cart",
      );
    });

    it("throws for negative quantity", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 1000), 1);
      expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    });

    it("throws for non-integer quantity", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 1000), 1);
      expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("removes all items", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 1000), 2);
      cart.add(makeProduct("b", 500), 3);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });

    it("is safe to call on empty cart", () => {
      const cart = new Cart();
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("itemCount", () => {
    it("returns 0 for empty cart", () => {
      expect(new Cart().itemCount).toBe(0);
    });

    it("sums quantities across all lines", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 100), 3);
      cart.add(makeProduct("b", 200), 7);
      expect(cart.itemCount).toBe(10);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy that does not affect internal state", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 1000), 2);
      const snap = cart.snapshot();
      snap[0]!.quantity = 999;
      snap[0]!.product.unitPriceCents = 0;
      // Original cart unchanged
      expect(cart.itemCount).toBe(2);
      expect(cart.totals().subtotalCents).toBe(2000);
    });
  });

  describe("totals (pricing pipeline)", () => {
    it("computes subtotal as sum of price * quantity", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 1000), 2); // 2000
      cart.add(makeProduct("b", 500), 3); // 1500
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(3500);
    });

    it("empty cart has all-zero totals", () => {
      const cart = new Cart();
      const totals = cart.totals();
      expect(totals).toEqual({
        subtotalCents: 0,
        discountCents: 0,
        taxCents: 0,
        shippingCents: 0,
        totalCents: 0,
      });
    });

    it("applies discount policy to subtotal", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(500),
      };
      const cart = new Cart({ discountPolicy });
      cart.add(makeProduct("a", 2000), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(500);
      expect(discountPolicy.computeDiscountCents).toHaveBeenCalledWith(2000);
    });

    it("clamps discount to [0, subtotal]", () => {
      // Discount exceeds subtotal
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(5000),
      };
      const cart = new Cart({ discountPolicy });
      cart.add(makeProduct("a", 2000), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(2000); // clamped to subtotal
    });

    it("clamps negative discount to 0", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ discountPolicy });
      cart.add(makeProduct("a", 2000), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(0);
    });

    it("computes tax on discounted subtotal", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(500),
      };
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(150),
      };
      const cart = new Cart({ discountPolicy, taxCalculator, region: "US" });
      cart.add(makeProduct("a", 2000), 1);
      const totals = cart.totals();
      // Tax is on discounted subtotal: 2000 - 500 = 1500
      expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(1500, "US");
      expect(totals.taxCents).toBe(150);
    });

    it("clamps negative tax to 0", () => {
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(-50),
      };
      const cart = new Cart({ taxCalculator });
      cart.add(makeProduct("a", 1000), 1);
      expect(cart.totals().taxCents).toBe(0);
    });

    it("passes lines and discounted subtotal to shipping calculator", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };
      const cart = new Cart({ discountPolicy, shippingCalculator });
      cart.add(makeProduct("a", 1000), 1);
      const totals = cart.totals();
      expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        800, // 1000 - 200
      );
      expect(totals.shippingCents).toBe(500);
    });

    it("clamps negative shipping to 0", () => {
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ shippingCalculator });
      cart.add(makeProduct("a", 1000), 1);
      expect(cart.totals().shippingCents).toBe(0);
    });

    it("computes totalCents as discountedSubtotal + tax + shipping", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(300),
      };
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(140),
      };
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };
      const cart = new Cart({ discountPolicy, taxCalculator, shippingCalculator });
      cart.add(makeProduct("a", 2000), 1);
      const totals = cart.totals();
      // subtotal=2000, discount=300, discountedSubtotal=1700
      // total = 1700 + 140 + 500 = 2340
      expect(totals.totalCents).toBe(2340);
    });

    it("defaults region to US", () => {
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(0),
      };
      const cart = new Cart({ taxCalculator });
      cart.add(makeProduct("a", 1000), 1);
      cart.totals();
      expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(1000, "US");
    });

    it("uses provided region", () => {
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(0),
      };
      const cart = new Cart({ taxCalculator, region: "FR" });
      cart.add(makeProduct("a", 1000), 1);
      cart.totals();
      expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
    });
  });

  describe("checkout", () => {
    let cart: Cart;

    beforeEach(() => {
      cart = new Cart();
      cart.add(makeProduct("a", 1000), 2);
      cart.add(makeProduct("b", 500, 300), 1);
    });

    it("returns totals and lines without collaborators", async () => {
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(2500);
      expect(result.lines).toHaveLength(2);
    });

    it("refreshes prices via priceFetcher", async () => {
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi
          .fn()
          .mockResolvedValueOnce(1200) // a → 1200
          .mockResolvedValueOnce(600), // b → 600
      };
      const result = await cart.checkout({ priceFetcher });
      // subtotal = 1200*2 + 600*1 = 3000
      expect(result.totals.subtotalCents).toBe(3000);
      expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
      expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("b");
    });

    it("throws InventoryError when item is unavailable", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          reason: "discontinued",
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InventoryError;
        expect(err.productId).toBe("a");
        expect(err.requested).toBe(2);
        expect(err.message).toBe("discontinued");
      }
    });

    it("throws InventoryError for partial-stock denial via availableQuantity", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 1, // less than requested 2
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InventoryError;
        expect(err.productId).toBe("a");
        expect(err.requested).toBe(2);
        expect(err.available).toBe(1);
      }
    });

    it("passes when availableQuantity meets requested", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 10,
        }),
      };
      const result = await cart.checkout({ inventoryChecker });
      expect(result.totals.subtotalCents).toBe(2500);
    });

    it("uses asyncTaxProvider for tax computation", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const cart = new Cart({ region: "US" });
      cart.add(makeProduct("a", 1000), 1);
      const result = await cart.checkout({ asyncTaxProvider });
      // subtotal=1000, no discount, tax = floor(1000*0.1) = 100
      expect(result.totals.taxCents).toBe(100);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
    });

    it("composes discount + async tax + shipping correctly", async () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(399),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.08),
      };
      const cart = new Cart({ discountPolicy, shippingCalculator, region: "US" });
      cart.add(makeProduct("x", 1000), 3); // subtotal = 3000
      const result = await cart.checkout({ asyncTaxProvider });
      // subtotal=3000, discount=200, discountedSubtotal=2800
      // tax = floor(2800*0.08) = 224
      // shipping = 399
      // total = 2800 + 224 + 399 = 3423
      expect(result.totals.subtotalCents).toBe(3000);
      expect(result.totals.discountCents).toBe(200);
      expect(result.totals.taxCents).toBe(224);
      expect(result.totals.shippingCents).toBe(399);
      expect(result.totals.totalCents).toBe(3423);
    });

    it("combines priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1000),
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.05),
      };
      const cart = new Cart();
      cart.add(makeProduct("a", 500), 2);
      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });
      // price refreshed to 1000, subtotal = 1000*2 = 2000
      // tax = floor(2000*0.05) = 100
      expect(result.totals.subtotalCents).toBe(2000);
      expect(result.totals.taxCents).toBe(100);
      expect(result.totals.totalCents).toBe(2100);
    });

    it("propagates priceFetcher rejection", async () => {
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
      };
      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
        "price service down",
      );
    });

    it("propagates asyncTaxProvider rejection", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
      };
      const cart = new Cart();
      cart.add(makeProduct("a", 1000), 1);
      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        "tax service down",
      );
    });

    it("generates default message for InventoryError when no reason given", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 0,
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (e) {
        const err = e as InventoryError;
        expect(err.message).toContain("insufficient stock");
        expect(err.message).toContain("a");
      }
    });

    it("checkout without collaborators returns snapshot lines", async () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 1000), 1);
      const result = await cart.checkout({});
      expect(result.lines).toHaveLength(1);
      expect(result.lines[0]!.product.id).toBe("a");
    });
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([
    [0, 0],
    [1000, 0],
    [-500, 0],
    [999999, 0],
  ])("computeDiscountCents(%i) returns %i", (subtotal, expected) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(expected);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "percent must be between 0 and 100"],
      [101, "percent must be between 0 and 100"],
      [NaN, "percent must be between 0 and 100"],
      [Infinity, "percent must be between 0 and 100"],
    ])("rejects out-of-range percent %s", (percent, msg) => {
      expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
      expect(() => new PercentageDiscountPolicy(percent)).toThrow(msg);
    });

    it.each([0, 50, 100])("accepts valid percent %i", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("computes 10% of 10000 = 1000", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(10000)).toBe(1000);
    });

    it("rounds down to nearest cent (33% of 100 = 33)", () => {
      const policy = new PercentageDiscountPolicy(33);
      expect(policy.computeDiscountCents(100)).toBe(33);
    });

    it("rounds down fractional cents (15% of 999 = 149)", () => {
      const policy = new PercentageDiscountPolicy(15);
      // 999 * 15 / 100 = 149.85 → floor → 149
      expect(policy.computeDiscountCents(999)).toBe(149);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-1000)).toBe(0);
    });

    it("100% discount returns full subtotal", () => {
      const policy = new PercentageDiscountPolicy(100);
      expect(policy.computeDiscountCents(5000)).toBe(5000);
    });

    it("0% discount returns 0", () => {
      const policy = new PercentageDiscountPolicy(0);
      expect(policy.computeDiscountCents(5000)).toBe(0);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "amountCents must be a non-negative integer"],
      [1.5, "amountCents must be a non-negative integer"],
    ])("rejects invalid amountCents %s", (amount, msg) => {
      expect(() => new FixedAmountDiscountPolicy(amount)).toThrow(RangeError);
      expect(() => new FixedAmountDiscountPolicy(amount)).toThrow(msg);
    });

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });

    it("accepts positive integer", () => {
      expect(() => new FixedAmountDiscountPolicy(500)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns fixed amount when subtotal exceeds it", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(1000)).toBe(500);
    });

    it("clamps to subtotal when fixed amount exceeds subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(1500);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("returns exact subtotal when amounts match", () => {
      const policy = new FixedAmountDiscountPolicy(1000);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policies array", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from multiple policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 10000 = 1000
          new FixedAmountDiscountPolicy(200), // min(200, 10000) = 200
        ],
        "sum",
      );
      expect(composite.computeDiscountCents(10000)).toBe(1200);
    });

    it("defaults to sum mode when not specified", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      expect(composite.computeDiscountCents(10000)).toBe(1200);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("clamps negative child results to 0 before summing", () => {
      // A custom policy that returns negative
      const negativePolicy = { computeDiscountCents: () => -500 };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(300)],
        "sum",
      );
      // -500 clamped to 0, plus 300 = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("can exceed subtotal (clamping is done by Cart)", () => {
      // Two 60% discounts should sum to 120% of subtotal
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(60), new PercentageDiscountPolicy(60)],
        "sum",
      );
      // 60% of 1000 = 600 each → 1200 total (exceeds 1000)
      expect(composite.computeDiscountCents(1000)).toBe(1200);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially to remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 10000 = 1000, remaining 9000
          new PercentageDiscountPolicy(10), // 10% of 9000 = 900, remaining 8100
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(10000)).toBe(1900);
    });

    it("fixed amount then percentage in chain mode", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(2000), // 2000 off, remaining 8000
          new PercentageDiscountPolicy(10), // 10% of 8000 = 800
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(10000)).toBe(2800);
    });

    it("order matters in chain mode", () => {
      // percentage first, then fixed
      const composite1 = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(50), // 50% of 1000 = 500, remaining 500
          new FixedAmountDiscountPolicy(300), // min(300, 500) = 300
        ],
        "chain",
      );
      expect(composite1.computeDiscountCents(1000)).toBe(800);

      // fixed first, then percentage
      const composite2 = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(300), // 300 off, remaining 700
          new PercentageDiscountPolicy(50), // 50% of 700 = 350
        ],
        "chain",
      );
      expect(composite2.computeDiscountCents(1000)).toBe(650);
    });

    it("chain stops reducing once remaining reaches 0", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(100), // 100% of 1000 = 1000, remaining 0
          new FixedAmountDiscountPolicy(500), // min(500, 0) = 0
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("clamps negative child results to 0 in chain mode", () => {
      const negativePolicy = { computeDiscountCents: () => -500 };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(300)],
        "chain",
      );
      // negative clamped to 0, then 300 applied to remaining 1000
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });
  });
});

