}

describe("Cart", () => {
  describe("add", () => {
    it("adds a product to the cart", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 1000), 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantity when adding same product twice", () => {
      const cart = new Cart();
      const product = makeProduct("a", 1000);
      cart.add(product, 2);
      cart.add(product, 3);
      expect(cart.itemCount).toBe(5);
    });

    it("rejects zero quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(makeProduct("a", 100), 0)).toThrow(RangeError);
    });

    it("rejects negative quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(makeProduct("a", 100), -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(makeProduct("a", 100), 1.5)).toThrow(RangeError);
    });

    it("rejects negative unitPriceCents", () => {
      const cart = new Cart();
      expect(() => cart.add(makeProduct("a", -1), 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes an existing product and returns true", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 1000), 1);
      expect(cart.remove("a")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product", () => {
      const cart = new Cart();
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity of existing product", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 1000), 2);
      cart.updateQuantity("a", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity is set to 0", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 1000), 2);
      cart.updateQuantity("a", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for unknown product", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("unknown", 5)).toThrow(
        "Product unknown is not in the cart",
      );
    });

    it("throws for negative quantity", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 1000), 1);
      expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    });

    it("throws for non-integer quantity", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 1000), 1);
      expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("removes all items", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 1000), 2);
      cart.add(makeProduct("b", 500), 3);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });

    it("is safe to call on empty cart", () => {
      const cart = new Cart();
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("itemCount", () => {
    it("returns 0 for empty cart", () => {
      expect(new Cart().itemCount).toBe(0);
    });

    it("sums quantities across all lines", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 100), 3);
      cart.add(makeProduct("b", 200), 7);
      expect(cart.itemCount).toBe(10);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy that does not affect internal state", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 1000), 2);
      const snap = cart.snapshot();
      snap[0]!.quantity = 999;
      snap[0]!.product.unitPriceCents = 0;
      // Original cart unchanged
      expect(cart.itemCount).toBe(2);
      expect(cart.totals().subtotalCents).toBe(2000);
    });
  });

  describe("totals (pricing pipeline)", () => {
    it("computes subtotal as sum of price * quantity", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 1000), 2); // 2000
      cart.add(makeProduct("b", 500), 3); // 1500
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(3500);
    });

    it("empty cart has all-zero totals", () => {
      const cart = new Cart();
      const totals = cart.totals();
      expect(totals).toEqual({
        subtotalCents: 0,
        discountCents: 0,
        taxCents: 0,
        shippingCents: 0,
        totalCents: 0,
      });
    });

    it("applies discount policy to subtotal", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(500),
      };
      const cart = new Cart({ discountPolicy });
      cart.add(makeProduct("a", 2000), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(500);
      expect(discountPolicy.computeDiscountCents).toHaveBeenCalledWith(2000);
