        [
          new FixedAmountDiscountPolicy(2000), // 2000 off, remaining 8000
          new PercentageDiscountPolicy(10), // 10% of 8000 = 800
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(10000)).toBe(2800);
    });

    it("order matters in chain mode", () => {
      // percentage first, then fixed
      const composite1 = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(50), // 50% of 1000 = 500, remaining 500
          new FixedAmountDiscountPolicy(300), // min(300, 500) = 300
        ],
        "chain",
