      // subtotal=3000, discount=200, discountedSubtotal=2800
      // tax = floor(2800*0.08) = 224
      // shipping = 399
      // total = 2800 + 224 + 399 = 3423
      expect(result.totals.subtotalCents).toBe(3000);
      expect(result.totals.discountCents).toBe(200);
      expect(result.totals.taxCents).toBe(224);
      expect(result.totals.shippingCents).toBe(399);
      expect(result.totals.totalCents).toBe(3423);
    });

    it("combines priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1000),
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.05),
      };
      const cart = new Cart();
      cart.add(makeProduct("a", 500), 2);
      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });
      // price refreshed to 1000, subtotal = 1000*2 = 2000
      // tax = floor(2000*0.05) = 100
      expect(result.totals.subtotalCents).toBe(2000);
      expect(result.totals.taxCents).toBe(100);
      expect(result.totals.totalCents).toBe(2100);
    });

    it("propagates priceFetcher rejection", async () => {
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
      };
      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
        "price service down",
      );
    });

    it("propagates asyncTaxProvider rejection", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
      };
      const cart = new Cart();
      cart.add(makeProduct("a", 1000), 1);
      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        "tax service down",
      );
    });

    it("generates default message for InventoryError when no reason given", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 0,
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (e) {
        const err = e as InventoryError;
        expect(err.message).toContain("insufficient stock");
        expect(err.message).toContain("a");
