import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

function makeLine(
  id: string,
  unitPriceCents: number,
  quantity: number,
  weightGrams?: number,
): CartLine {
  return {
    product: { id, name: id, unitPriceCents, weightGrams },
    quantity,
  };
}

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });

  it("returns 0 for non-empty cart", () => {
    const lines = [makeLine("a", 1000, 2)];
    expect(calc.computeShippingCents(lines, 2000)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(4.5)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 99.5)).toThrow(RangeError);
    });

    it("accepts valid constructor args", () => {
      expect(() => new FlatShippingCalculator(500, 5000)).not.toThrow();
    });

    it("accepts zero flatCents", () => {
      expect(() => new FlatShippingCalculator(0)).not.toThrow();
    });

    it("accepts zero freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(500);
      expect(calc.computeShippingCents([], 0)).toBe(0);
    });

    it("returns flat fee for non-empty cart without threshold", () => {
      const calc = new FlatShippingCalculator(799);
      const lines = [makeLine("a", 1000, 1)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(799);
    });

    it("returns flat fee when subtotal is below threshold", () => {
      const calc = new FlatShippingCalculator(500, 5000);
      const lines = [makeLine("a", 2000, 1)];
      expect(calc.computeShippingCents(lines, 2000)).toBe(500);
    });

    it("returns 0 when subtotal equals threshold", () => {
      const calc = new FlatShippingCalculator(500, 5000);
      const lines = [makeLine("a", 5000, 1)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds threshold", () => {
      const calc = new FlatShippingCalculator(500, 5000);
      const lines = [makeLine("a", 6000, 1)];
      expect(calc.computeShippingCents(lines, 6000)).toBe(0);
    });

    it("returns flat fee when freeOverCents is undefined", () => {
      const calc = new FlatShippingCalculator(500);
      const lines = [makeLine("a", 100000, 1)];
      expect(calc.computeShippingCents(lines, 100000)).toBe(500);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with zero upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 0, costCents: 500 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: -100, costCents: 500 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with non-integer upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1.5, costCents: 500 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1000, costCents: -1 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with non-integer costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1000, costCents: 5.5 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects invalid overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 5000, costCents: 1200 },
      ],
      2000,
    );

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns 0 when total weight is 0 (no weightGrams)", () => {
      const lines = [makeLine("a", 1000, 1)]; // no weight
      expect(calc.computeShippingCents(lines, 1000)).toBe(0);
    });

    it("selects first bracket for weight within it", () => {
      const lines = [makeLine("a", 1000, 1, 300)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("selects first bracket at exact boundary", () => {
      const lines = [makeLine("a", 1000, 1, 500)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("selects second bracket just above first boundary", () => {
      const lines = [makeLine("a", 1000, 1, 501)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(700);
    });

    it("selects last bracket at its boundary", () => {
      const lines = [makeLine("a", 1000, 1, 5000)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(1200);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const lines = [makeLine("a", 1000, 1, 5001)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(2000);
    });

    it("falls back to heaviest bracket cost when no overflow specified", () => {
      const calcNoOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
      ]);
      const lines = [makeLine("a", 1000, 1, 3000)];
      expect(calcNoOverflow.computeShippingCents(lines, 1000)).toBe(700);
    });

    it("sorts brackets internally regardless of input order", () => {
      const calcUnsorted = new WeightBasedShippingCalculator([
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 500, costCents: 300 },
      ]);
      const lines = [makeLine("a", 1000, 1, 400)];
      expect(calcUnsorted.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("sums weight across multiple lines with quantity", () => {
      // 200g * 2 = 400g + 600g * 1 = 600g → total 1000g → second bracket (700)
      const lines = [
        makeLine("a", 1000, 2, 200),
        makeLine("b", 500, 1, 600),
      ];
      expect(calc.computeShippingCents(lines, 2500)).toBe(700);
    });
  });
});

